def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    lowest = min(values)
    return {
        "value": lowest,
        "trace": {
            "values": values,
            "lowest": lowest,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
